// EI-18, OP-149 m.6, OP-154 m.3 (k): the session's device Instance, the same one the account
// pages keep. Its P-256 key is generated by WebCrypto as non-extractable and kept in IndexedDB on
// this origin; it never leaves this browser. AIS bytes are encoded and decoded by the Kernel
// (Wasm); WebCrypto signs them. The consent page signs only after it showed the decoding.
import { loadKernel, type Kernel } from "@esuiss/access";

import { REALM } from "./base.js";

const DB = "access-account";
const STORE = "instances";
const ESP256 = -9;
const CSRF_COOKIE = "__Host-access-account-csrf";
// P-256 group order (SEC 2) for the low-S form the Kernel requires (CR-9)
const N = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;

/** The account BFF of this realm. */
export const ACCOUNT_API = `${REALM}/account/api`;

/** A device Instance as this browser keeps it, in the account pages' record shape. */
export interface Instance {
  readonly id: string;
  readonly key: CryptoKey;
  readonly kid: Uint8Array;
  readonly domain: Uint8Array;
  readonly basis: Uint8Array;
  readonly publicBasis: string;
  readonly pep: string;
  readonly party: string;
}

/** The account session as the BFF reports it. */
export interface Session {
  readonly realm: string;
  readonly account: string;
  readonly domain: string;
  readonly party: string | null;
  readonly instance: string | null;
  readonly pep: string;
}

/** What the person is shown before signing: the Kernel's decoding of the exact bytes. */
export interface Decoded {
  readonly action: string;
  readonly domain: string;
  readonly until: string;
}

/** Not signed: cancelled, or the bytes did not match what was asked for. */
export class NotSigned extends Error {}

export function b64url(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export function fromB64url(text: string): Uint8Array {
  const s = atob(text.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(s, (c) => c.charCodeAt(0));
}

function open(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => {
      r.result.createObjectStore(STORE, { keyPath: "id" });
    };
    r.onsuccess = () => {
      resolve(r.result);
    };
    r.onerror = () => {
      reject(r.error ?? new Error("indexeddb"));
    };
  });
}

async function tx<T>(mode: IDBTransactionMode, f: (s: IDBObjectStore) => IDBRequest): Promise<T> {
  const db = await open();
  return new Promise<T>((resolve, reject) => {
    const r = f(db.transaction(STORE, mode).objectStore(STORE));
    r.onsuccess = () => {
      resolve(r.result as T);
    };
    r.onerror = () => {
      reject(r.error ?? new Error("indexeddb"));
    };
  });
}

function csrf(): string {
  for (const part of document.cookie.split(";")) {
    const [name, value] = part.trim().split("=", 2);
    if (name === CSRF_COOKIE && value !== undefined) return value;
  }
  return "";
}

/** A call to the account BFF; every write carries its CSRF token. */
export async function account<T>(path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { accept: "application/json" };
  const init: RequestInit = { headers, credentials: "same-origin", cache: "no-store" };
  if (body !== undefined) {
    init.method = "POST";
    headers["content-type"] = "application/json";
    headers["x-csrf-token"] = csrf();
    init.body = JSON.stringify(body);
  }
  const r = await fetch(`${ACCOUNT_API}${path}`, init);
  if (!r.ok) throw new NotSigned(String(r.status));
  return (await r.json()) as T;
}

function lowS(sig: Uint8Array): Uint8Array {
  const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
  const s = BigInt(`0x${hex(sig.slice(32))}`);
  if (s <= N / 2n) return sig;
  const t = (N - s).toString(16).padStart(64, "0");
  const out = Uint8Array.from(sig);
  for (let i = 0; i < 32; i++) out[32 + i] = Number.parseInt(t.slice(i * 2, i * 2 + 2), 16);
  return out;
}

export async function sign(
  key: CryptoKey,
  k: Kernel,
  kid: Uint8Array,
  statement: Uint8Array,
): Promise<string> {
  const protectedHeader = k.aisProtected(ESP256, kid);
  const tbs = Uint8Array.from(k.coseToBeSigned(protectedHeader, statement));
  const raw = new Uint8Array(
    await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, tbs),
  );
  return b64url(k.coseSign1(protectedHeader, statement, lowS(raw)));
}

/** The Kernel's decoding of an intent, as the screen shows it. */
export function decode(k: Kernel, envelope: Uint8Array, domain: string): Decoded {
  const d = JSON.parse(k.describeIntent(envelope)) as {
    action: { namespace: string; name: string };
    validity: { until: string };
  };
  return {
    action: `${d.action.namespace}.${d.action.name}`,
    domain,
    until: new Date(Number(d.validity.until)).toISOString(),
  };
}

/** This browser's key for the session's Instance, if it has it. */
export async function find(s: Session): Promise<Instance | undefined> {
  if (s.instance === null) return undefined;
  try {
    return await tx<Instance | undefined>("readonly", (st) =>
      st.get(`${s.realm}/${s.account}/${s.instance ?? ""}`),
    );
  } catch {
    return undefined;
  }
}

interface Challenge {
  readonly challenge: string;
  readonly domain: string;
  readonly basis: string;
  readonly pep: string;
  readonly party: string;
  readonly valid_from: string;
  readonly valid_until: string;
  readonly create: string;
  readonly register?: string;
}

/**
 * Registers this browser as the session's device Instance (OP-149 m.6): a fresh
 * non-extractable P-256 key, its own `instance_create` Exercise, signed only when `confirm`
 * accepts the Kernel's decoding, the key kept in IndexedDB for the account pages too.
 */
export async function register(
  s: Session,
  confirm: (d: Decoded) => Promise<boolean>,
): Promise<Instance> {
  const k = await loadKernel();
  const pair = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, false, [
    "sign",
  ]);
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", pair.publicKey));
  const [x, y] = [raw.slice(1, 33), raw.slice(33, 65)];
  const kid = k.thumbprintP256(x, y);
  const coseKey = k.coseKeyP256(x, y);
  const c = await account<Challenge>("/instances/challenge", { key: b64url(coseKey) });
  const domain = fromB64url(c.domain);
  const basis = k.exerciseBasis("public", fromB64url(c.basis));
  const challenge = fromB64url(c.challenge);
  const envelopes = [c.create, ...(c.register === undefined ? [] : [c.register])].map(fromB64url);
  const nonces = [challenge, Uint8Array.from([...challenge, 0x01])];
  const iat = BigInt(Date.now());
  const statements = envelopes.map((e, i) =>
    k.aisStatement(
      domain,
      nonces[i] ?? challenge,
      k.intentDigest(e),
      "commit",
      c.pep,
      new Uint8Array(),
      basis,
      iat,
      new Uint8Array(),
    ),
  );
  const first = envelopes[0];
  if (first === undefined) throw new NotSigned("no statement");
  if (!(await confirm(decode(k, first, c.domain)))) throw new NotSigned("cancelled");
  const signed = await Promise.all(statements.map((st) => sign(pair.privateKey, k, kid, st)));
  const body: Record<string, string> = {
    challenge: c.challenge,
    party: c.party,
    key: b64url(coseKey),
    valid_from: c.valid_from,
    valid_until: c.valid_until,
    ais: signed[0] ?? "",
  };
  if (signed[1] !== undefined) body["register_ais"] = signed[1];
  await account("/instances", body);
  const instance: Instance = {
    id: `${s.realm}/${s.account}/${b64url(kid)}`,
    key: pair.privateKey,
    kid,
    domain,
    basis,
    publicBasis: c.basis,
    pep: s.pep,
    party: c.party,
  };
  await tx("readwrite", (st) => st.put(instance));
  return instance;
}
